/**
 * `npm run legal:build` — copies the legal Markdown (packages/shared/src/legal/*.md) into
 * content.generated.ts, which the API bundle and the app import (docs/17). The Markdown is the
 * source of truth; scripts/legal-build.test.ts fails in CI when the generated file is stale.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const LEGAL_DIR = join(dirname(fileURLToPath(import.meta.url)), '../packages/shared/src/legal');
export const GENERATED_PATH = join(LEGAL_DIR, 'content.generated.ts');

const DOCUMENTS = ['privacy', 'terms'] as const;
const LANGUAGES = ['et', 'en', 'ru'] as const;

export function buildLegalModule(dir = LEGAL_DIR): string {
  const content = Object.fromEntries(
    DOCUMENTS.map((doc) => [doc, Object.fromEntries(LANGUAGES.map((lang) => [lang, readFileSync(join(dir, `${doc}.${lang}.md`), 'utf8')]))]),
  );
  return [
    '// GENERATED by `npm run legal:build` from the *.md files next to this file — do not edit by hand.',
    '',
    `export const LEGAL_MARKDOWN = ${JSON.stringify(content, null, 2)} as const;`,
    '',
  ].join('\n');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(GENERATED_PATH, buildLegalModule());
  console.log(`wrote ${GENERATED_PATH}`);
}
